theorem.raw:
\label{Th2}
Let $(\mathrm{M},\mathrm{g})$ be a simple compact Riemannian manifold with boundary of dimension $n \geq 2$ such that $k^+(\mathrm{M},\mathrm{g})<1$, and let $T>\textrm{Diam}_\mathrm{g}(\mathrm{M})$.
There exist  $C>0$ and $\gamma\in(0,1)$ such that for any $a_1,a_2\in\mathscr{A}(m_1,\eta)$ and $q_1,q_2\in\mathscr{Q}(m_2)$ coincide near the boundary $\partial\mathrm{M}$, the following estimate holds true
\begin{equation}\label{1.12}
\norm{a_1-a_2}_{L^2(\mathrm{M})}+\norm{q_1-q_2}_{L^2(\mathrm{M})}\leq C\norm{\Lambda_{a_1,q_1}-\Lambda_{a_2,q_2}}^\gamma
\end{equation}
where $C$ depends on $\mathrm{M}$, $m_1,m_2$, $\eta$ and $n$.

\label{theorem}
For every simple compact Riemannian manifold $(\mathrm{M},\mathrm{g})$ with $k^+(\mathrm{M},\mathrm{g})<1$, there exist $C>0$ such that the following stability estimate 
\begin{equation}\label{2.10}
 \Vert f \Vert _{L^2(\mathrm{M})}\leq C \Vert \mathcal{I} f \Vert_{H^1(\partial_+S\mathrm{M})}, 
\end{equation} 
holds for any $f\in H^1(\mathrm{M})$.

lemma.raw:
\label{L.1.1}
Let $T>0$, $a\in L^\infty(\mathrm{M})$, and $q\in L^\infty(\mathrm{M})$. Assuming $F\in H^1(0,T;L^2(\mathrm{M}))$ such that $F(\cdot,0)=0$ in $\mathrm{M}$, then there exists a unique solution
$v$ to \eqref{1.4} such that
 $$
 v\in \mathcal{C}^2(0,T;L^2(\mathrm{M}))\cap \mathcal{C}^1(0,T;H^1_0(\mathrm{M}))\cap \mathcal{C}(0,T; H^2(\mathrm{M})).
 $$ 
 Furthermore, there is a constant $C>0$ such that
\begin{equation}\label{1.5}
\norm{\partial_tv(\cdot,t)}_{L^2(\mathrm{M})}+\norm{\nabla v(\cdot,t)}_{L^2(\mathrm{M})}\leq
C\norm{F}_{L^2(Q)},
\end{equation}
and
\begin{equation}\label{1.6}
\norm{\partial_t^2 v(\cdot,t)}_{L^2(\mathrm{M})}+\norm{\nabla\partial_t v(\cdot,t)}_{L^2(\mathrm{M})}+\norm{\Delta v(\cdot,t)}_{L^2(\mathrm{M})}\leq C\norm{F}_{H^1(0,T;L^2(\mathrm{M}))}.
\end{equation}

\label{L.1.2}
Let $f\in H^1(\Sigma)$ be a function such that $f(x,0)=0$ for all $x\in\partial\mathrm{M}$.
There exists an unique solution
\begin{equation}\label{1.7}
u\in \mathcal{C}^1(0,T;L^2(\mathrm{M}))\cap \mathcal{C}(0,T;H^1(\mathrm{M}))
\end{equation}
to the problem (\ref{1.1}).  Furthermore, there is a
constant $C>0$ such that
\begin{equation}\label{1.8}
\norm{\partial_\nu u}_{L^2(\Sigma)}\leq C\norm{f}_{H^1(\Sigma)}.
\end{equation}

\label{L.2.2}
The function $u$ given by (\ref{2.34}) is smooth on $T\mathrm{M}\backslash T(\partial\mathrm{M})$ and has the following properties:
\begin{enumerate}
\item  $u$ is homogeneous function of degree $-1$  in $\xi$.
\item  $u$ satisfies the following kinetic equation $Hu=-f$.
\item $u$ satisfies the following equation $H\overset{\mathrm{v}}{\nabla} u=-\overset{\mathrm{h}}{\nabla} u$.
\end{enumerate}

\label{L.2.3}
Let $(\mathrm{M},\mathrm{g})$ be a simple Riemannian manifold and $K^+$ given by (\ref{2.8}). Let a semibasic tensor field $u\in\mathcal{C}^\infty(\beta_m^0\mathrm{M})$ satisfies boundary condition (\ref{2.36}), then the following inequality 
\begin{equation}\label{2.37}
\int_{S\mathrm{M}} K^+(x,\xi) \vert u(x,\xi) \vert ^2 \,\mathrm{dv}^{2n-1} \leq k^+\int_{S\mathrm{M}} \vert Hu(x,\xi) \vert ^2 \,\mathrm{dv}^{2n-1}.
\end{equation}
holds true. Here $k^+=k^+(\mathrm{M},\mathrm{g})$ is given by (\ref{2.9}).

\label{L.3.1}
 For $y\in\partial\mathrm{M}_1$, we denote the function $\varrho(x)=d_\mathrm{g}(y,x)$. Then $\varrho\in\mathcal{C}^2(\mathrm{M})$ and satisfies the eikonal equation 
\begin{equation}\label{3.7}
\abs{\nabla\varrho}^2=\mathrm{g}^{ij}\frac{\partial\varrho}{\partial x_i}\frac{\partial\varrho}{\partial
x_j}=1,\qquad \forall x\in \mathrm{M}.
\end{equation}

\label{L.3.2}
 Let  $a\in W^{2,\infty}(\mathrm{M})$, $q\in W^{2,\infty}(\mathrm{M})$, and $\theta\in\mathcal{V}(Q)$, $\psi_{a}\in\mathcal{W}(Q)$ solve respectively (\ref{3.11}) and (\ref{3.12}). Then for all $h>0$ small enough, there exists a solution 
 $$
 u(x,t;h)\in \mathcal{C}^2(0,T;L^2(\mathrm{M}))\cap\mathcal{C}^1(0,T;H^1(\mathrm{M}))\cap\mathcal{C}(0,T;H^2(\mathrm{M}))
 $$ 
 of the wave equation
\begin{equation*}
(\partial^2_t-\Delta+a(x)\partial_t+q(x))u=0,\quad \textrm{in}\quad Q,
\end{equation*}
with the initial condition
\begin{equation*}
u(x,0)=\partial_tu(x,0)=0,\quad \textrm{in}\quad \mathrm{M},
\end{equation*}
 of the form
\begin{equation}\label{3.24}
u(x,t)=\theta(x,t)\psi_a(x,t)e^{i\varphi(x,t)/h}+r_h(x,t),
\end{equation}
the remainder $r_h(x,t)$ is such that
\begin{align*}
r_h(x,t)&=0,\quad (x,t)\in \Sigma , \\
r_h(x,0)=\partial_t r_h(x,0)&=0,\quad x\in \mathrm{M}.
\end{align*}
Furthermore, there exist $C>0$, $h_0>0$ such that, for all $h \leq h_0$ the following estimates hold true.
\begin{equation}\label{3.25}
\sum_{k=0}^2 \sum_{j=0}^{k} h^{k-1} \|\partial_t^{j} r_h(\cdot,t)\|_{H^{k-j}(\mathrm{M})}\leq C\norm{\theta}_{\mathcal{V}(Q)}.
\end{equation}
The constant $C$ depends only on $T$ and $\mathrm{M}$ (that is $C$ does
not depend on $a$ and $h$).

\label{L.3.3} Let  $a\in W^{2,\infty}(\mathrm{M})$, $q\in W^{2,\infty}(\mathrm{M})$, and $\theta\in\mathcal{V}(Q)$, $\psi_{-a}\mathcal{W}(Q)$ solve respectively (\ref{3.11}) and (\ref{3.12}) (with $a$ replaced by $-a$). Then for all $h>0$ small enough, there exists a solution 
$$
u(x,t;h)\in \mathcal{C}^2(0,T;L^2(\mathrm{M}))\cap\mathcal{C}^1(0,T;H^1(\mathrm{M}))\cap\mathcal{C}(0,T;H^2(\mathrm{M}))
$$ of the wave equation
\begin{equation*}
(\partial^2_t-\Delta-a(x)\partial_t+q(x))u=0,\quad \textrm{in}\quad Q,
\end{equation*}
with the final condition
\begin{equation*}
u(T,x)=\partial_tu(T,x)=0,\quad \textrm{in}\quad \mathrm{M},
\end{equation*}
 of the form
\begin{equation}\label{3.35}
u(x,t;h)=\theta(x,t)\psi_{-a}(x,t)e^{i\varphi(x,t)/h}+r_h(x,t),
\end{equation}




the remainder $r_h(t,x)$ is such that
\begin{align*}
r_h(x,t)&=0,\quad (x,t)\in \Sigma , \\
r_h(x,T)=\partial_tr_h(x,T)&=0,\quad x\in \mathrm{M}.
\end{align*}
Furthermore, there exist $C>0$, $h_0>0$ such that, for all $h \leq h_0$ the following estimates hold true.
\begin{equation}\label{3.36}
\sum_{k=0}^2 \sum_{j=0}^{k} h^{k-1} \|\partial_t^{j} r_h(\cdot,t)\|_{H^{k-j}(\mathrm{M})}\leq C\norm{\theta}_{\mathcal{V}(Q)}.
\end{equation}
The constant $C$ depends only on $T$ and $\mathrm{M}$ (that is $C$ does
not depend on $a$ and $h$).

\label{L.4.1}
Let $T>0$. There exist $C>0$ such that for any $\theta_j\in \mathcal{V}(Q)$, $j=1,2$, 
satisfying the transport equation (\ref{3.7}), the following estimate holds true:
\begin{equation}\label{4.2}
\abs{\int_{0}^T\!\!\!\!\int_{\mathrm{M}}a(x)(\theta_2\overline{\theta}_1)(x,t)\psi_{a}(x,t)\,\,\mathrm{dv}^{n} \, \mathrm{d} t } 
\leq C\para{h+h^{-2}\norm{\Lambda_{a_1,q_1}-\Lambda_{a_2,q_2}}}\norm{\theta_1}_{\mathcal{V}(Q)}\norm{\theta_2}_{\mathcal{V}(Q)}
\end{equation}
for all $h\in (0,h_0)$.

\label{L.4.2} There exists $C>0$ such that for any $\Psi\in H^2 (S_y\mathrm{M}_{1})$, the following estimate
\begin{multline}\label{4.13}
\abs{\int_{S^+_{y}\mathrm{M}_1}\para{\exp\para{-\frac{1}{2}\mathcal{I}(a)(y,\xi)}-1}
\Psi(\xi)  \,  
\mathrm{d}\omega_y(\xi)}\cr
 \leq C\para{h+h^{-2}\norm{\Lambda_{a_1,q_1}-\Lambda_{a_2,q_2}}} \norm{\Psi}_{H^2(S_y\mathrm{M}_{1})}.
\end{multline}
holds for any $y\in\partial\mathrm{M}_1$.

\label{L.4.3}
Let $\Psi_\kappa$ given by (\ref{4.16}), $\kappa \in (0,1)$. Then we have the following properties:
\begin{equation}\label{4.17}
\displaystyle 0\leq\Psi_\kappa(\theta,\xi)\leq \frac{2}{\alpha_n(1-\kappa)^{n-1}},\quad \forall\, \kappa\in (0,1),\,\forall\,\xi,\theta \in S_y\mathrm{M}_1.
\end{equation}  
\begin{equation}\label{4.18}
 \displaystyle \int_{S_y\mathrm{M}_1}\Psi_\kappa(\theta,\xi) d\omega_y(\xi)=1,\quad \forall \kappa\in (0,1),\,\forall\,\theta \in S_y\mathrm{M}_1.
\end{equation} 
\begin{equation}\label{4.19}
\int_{S_y\mathrm{M}_1}\Psi_\kappa(\theta,\xi) \abs{\theta-\xi}d\omega_y(\xi)\leq C(1-\kappa)^{1/2n}, \quad \forall\, \kappa\in (0,1),\,\forall\,\theta \in S_y\mathrm{M}_1.
\end{equation}
\begin{equation}\label{4.20}
\norm{ \Psi_\kappa(\theta,\cdot)}_{H^2(S_y\mathrm{M}_1)}^2\leq \frac{C}{(1-\kappa)^{n+3}}, \quad \forall \kappa\in (0,1),\,\forall\,\theta \in S_y\mathrm{M}_1.
\end{equation}

\label{L.4.4}
 Let $a_{i}\in \mathscr{A}(m_{1},\alpha)$, $q_i \in \mathscr{Q}(m_2)$, $i=1,\,2$. There exist $C>0,$
$\delta>0$, $\beta>0$ and $h_{0}>0$ such that 
\begin{equation}\label{4.21}
|\mathcal{I}(a)(y,\theta)|\leq C \Big( h^{-\delta}\|\Lambda_{a_{2},q_{2}}-\Lambda_{a_{1},q_{1}}\|+h^{\beta}  \Big),\quad\forall \, (y,\theta)\in\partial_+S\mathrm{M}_1,
\end{equation}
for any $h\leq h_{0}$. Here $C$ depends only on $\mathrm{M}$, $T$,
$m_{1}$ and $m_{2}$.

\label{L.5.1}
Let $T>0$. There exist $C>0$ such that for any $\theta_j\in \mathcal{V}(Q)$, $j=1,2$, 
satisfying the transport equation (\ref{3.11}), the following estimate holds true:
\begin{equation}\label{5.2}
\abs{\int_{0}^T\!\!\!\!\int_{\mathrm{M}}q(x)(\theta_2\overline{\theta}_1)(x,t)\,\,\mathrm{dv}^{n} \, \mathrm{d} t } 
\leq C\para{h+h^{-1} \|a\|_{\mathcal{C}^0(\mathrm{M})}+h^{-3}\norm{\Lambda_{a_1,q_1}-\Lambda_{a_2,q_2}}}\norm{\theta_1}_{\mathcal{V}(Q)}\norm{\theta_2}_{\mathcal{V}(Q)}
\end{equation}
for all $h\in (0,h_0)$.

\label{L.5.2} There exists $C>0$ such that for any $\Psi\in H^2 (S_y\mathrm{M}_{1})$, the following estimate
\begin{equation}\label{5.7}
\bigg|\int_{S_{y}\mathrm{M}_1}\mathcal{I} q(y,\xi)
\Psi(\xi)  \,  \,
\mathrm{d}\omega_y(\xi)\bigg|
\leq C\para{h+h^{-1} \norm{a}_{\mathcal{C}^0(\mathrm{M})}+h^{-3}\norm{\Lambda_{a_1,q_1}
-\Lambda_{a_2,q_2}}
} \norm{\Psi}_{H^2(S^+_y\mathrm{M}_{1})},
\end{equation}
holds for any $y\in\partial\mathrm{M}_1$.

\label{L.5.3}
 Let $a_{i}\in \mathscr{A}(m_1,\alpha)$, $q_i\in \mathscr{Q}(m_2)$, $i=1,\,2$. There exist $C>0,$
$\delta>0$, $\beta>0$ and $h_{0}>0$ such that 
\begin{equation}\label{5.11}
|\mathcal{I}(q)(y,\theta)|\leq C \Big( h^{-\delta}\|\Lambda_{a_{2},b_{2}}-\Lambda_{a_{1},b_{1}}\|+ h^{-\delta}\|a\|_{\mathcal{C}^0(\mathrm{M})}+h^{\beta}  \Big),\quad\forall \, (y,\theta)\in\partial_+S\mathrm{M}_1,
\end{equation}
for any $h\leq h_{0}$. Here $C$ depends only on $\mathrm{M}$, $T$,
$m_{1}$ and $m_{2}$.

proof.raw:
By the simplicity assumption, since $y\notin\overline{\mathrm{M}}$, we have $\varrho\in\mathcal{C}^\infty(\mathrm{M})$, and in polar normal coordinates, we get
\begin{equation}\label{3.8}
\widetilde{\varrho}(r,\xi)=r=d_\mathrm{g}(y,x).
\end{equation}
The proof is complete.

Let $r(x,t;h)$ solves the following 
homogenous boundary value problem
\begin{equation}\label{3.26}
\left\{
\begin{array}{llll}
\para{\partial^2_t-\Delta+a(x)\partial_t+q(x)}r(x,t)=V_h (x,t)
& \textrm{in }\,\, Q,\cr
r(x,0)=\partial_tr(x,0)=0,& \textrm{in
}\,\,\mathrm{M},\cr
r(x,t)=0 & \textrm{on} \,\, \Sigma.
\end{array}
\right.
\end{equation}
where the source term $V_h$ is given by 
\begin{equation}\label{3.27}
V_h(x,t)=-\para{\partial_t^2-\Delta+a(x)\partial_t+q(x)}\para{(\theta\psi_a)(x,t)e^{i\varphi/h}}.
\end{equation}
To prove our Lemma it would be enough to show that $r$ satisfies the estimates (\ref{3.25}).\\
By a simple computation, we have
\begin{align}\label{3.28}
-V_h (x,t)&=e^{i\varphi(x,t)/h}\para{\partial_t^2-\Delta+a(x)\partial_t+q(x)}\para{(\theta\psi_a)( x,t)}\cr
&\quad -\frac{2i}{h} e^{i\varphi(x,t)/h}\psi_a(x,t)\para{\partial_t\theta+\seq{d\varrho,d\theta}+\frac{\theta}{2}\Delta\varrho}( x,t)\cr
&\quad -\frac{2i}{h} e^{i\varphi(x,t)/h}\theta(x,t)\para{\partial_t\psi_a+\seq{d\varrho,d\psi_a}+\frac{a}{2} \psi_a}(x,t)\cr
&\quad-\frac{1}{h^2} \theta\psi_a(x,t) e^{i\varphi(x,t)/h}\para{1-\abs{d\varrho}^2}.
\end{align}
Taking into account  (\ref{3.7})-(\ref{3.11}) and (\ref{3.12}), the right-hand side of (\ref{3.28}) becomes
\begin{align}\label{3.29}
V_h (x,t)&=-e^{i\varphi(x,t)/h}(\partial_t^2-\Delta+a(x)\partial_t+q(x))\para{(\theta\psi_a)(x,t)}
\cr &\equiv-e^{i\varphi(x,t)/h}V_0(x,t).
\end{align}
Since $\theta\in\mathcal{V}(Q)$ and $\psi_a\in\mathcal{W}(Q)$ we deduce that $V_0\in H^1_0(0,T;L^2(\mathrm{M}))$. 
Furthermore, there is a constant $C>0$, such that
\begin{equation}\label{3.30}
\norm{V_0}_{L^2(Q)}+\norm{\partial_tV_0}_{L^2(Q)}\leq C\norm{\theta}_{\mathcal{V}(Q)}.
\end{equation}
By Lemma \ref{L.1.1}, we find
\begin{equation}\label{3.31}
r_h\in \mathcal{C}^2(0,T;L^2(\mathrm{M}))\cap\mathcal{C}^1(0,T;H^1_0(\mathrm{M}))\cap\mathcal{C}(0,T;H^2(\mathrm{M})).
\end{equation}
Since the coefficients $a$ and $q$ do not depend on $t$, the function
$$
r^*_h(x,t)=\int_0^tr_h(x,s)ds,
$$
solves the mixed hyperbolic problem (\ref{3.26}) with the right side
$$
V^*_h(x,t)=\int_0^tV_h (x,s)ds=-ih\int_0^tV_0(x,s)\partial_s\para{e^{i\varphi(x,s)/h}}ds.
$$
Integrating by part with respect to $s$, we conclude that
$$
\norm{V^*_h}_{L^2(Q)}\leq Ch\norm{\theta}_{\mathcal{V}(Q)}.
$$
and by (\ref{1.5}), we get
\begin{eqnarray}\label{3.32}
\norm{r_h(\cdot,t)}_{L^2(\mathrm{M})}=\norm{\partial_tr^*_h(\cdot,t)}_{L^2(\mathrm{M})}\leq
Ch\norm{\theta}_{\mathcal{V}(Q)}.
\end{eqnarray}
Since $\norm{V_h }_{L^2(Q)}+h\norm{\partial_tV_h }_{L^2(Q)}\leq C\norm{\theta}_{\mathcal{V}(Q)}$, by using again the energy estimates for the problem (\ref{3.26}), obtain
\begin{eqnarray}\label{3.33}
\norm{\partial_tr_h(\cdot,t)}_{L^2(\mathrm{M})}+\norm{\nabla r_h (\cdot,t)}_{L^2(\mathrm{M})}\leq C\norm{\theta}_{\mathcal{V}(Q)}.
\end{eqnarray}
and by (\ref{1.6}), we have
\begin{eqnarray}\label{3.34}
\norm{\partial_t^2 r_h(\cdot,t)}_{L^2(\mathrm{M})}+\norm{\nabla\partial_t r_h(\cdot,t)}_{L^2(\mathrm{M})}+\norm{\Delta r_h(\cdot,t)}_{L^2(\mathrm{M})}\leq Ch^{-1}\norm{\theta}_{\mathcal{V}(Q)}.
\end{eqnarray}
Collecting (\ref{3.32})-(\ref{3.33}) and (\ref{3.34}) we get (\ref{3.25}).
The proof is complete.

We take two solutions to (\ref{3.11}) of the form
\begin{align*}
\widetilde{\theta}_1(t,r,\xi)&=\alpha^{-1/4}\phi(t-r)\Psi(\xi), \\
\widetilde{\theta}_2(t,r,\xi)&=\alpha^{-1/4}\phi(t-r).
\end{align*}
Now we change variable in the left term of (\ref{4.1}), $x=\exp_{y}(r\xi)$, $r>0$ and
$\xi\in S_{y}\mathrm{M}_1$, we have
\begin{multline}\label{4.14}
\int_0^T\!\!\int_\mathrm{M} a(x) (\overline{\theta}_1\theta_2)(x,t)\psi_{a}(x,t)  \,\mathrm{dv}^{n} \, \mathrm{d} t \cr
=\int_0^T\!\!\int_{S^+_{y}\mathrm{M}_1}\!\int_0^{\ell_+(y,\xi)}\widetilde{a}(r,y,\xi)(\overline{\widetilde{\theta}}_1\widetilde{\theta}_2)( t,r,\xi)
\widetilde{\psi}_{a}( t,r,\xi)
\alpha^{1/2} \, \mathrm{d} r \, \mathrm{d}\omega_y(\xi) \, \mathrm{d} t\cr
=\int_0^T\!\!\int_{S^+_{y}\mathrm{M}_1}\!\int_0^{\ell_+(y,\xi)}\widetilde{a}(r,y,\xi)\phi^2( t-r)\widetilde{\psi}_{a}( t,r,\xi)\Psi(\xi)  \, \mathrm{d} r \,
\mathrm{d}\omega_y(\xi)
\, \mathrm{d} t\cr
=\int_0^T\!\!\int_{S^+_{y}\mathrm{M}_1}\!\int_\mathbb{R} \widetilde{a}( t-\tau,y,\xi)\phi^2(\tau)\widetilde{\psi}_{a}( t, t-\tau,\xi)\Psi(\xi) \, \mathrm{d} \tau \,
\mathrm{d}\omega_y(\xi)
\, \mathrm{d} t\cr
=\int_0^T\!\!\int_{S^+_{y}\mathrm{M}_1}\!\int_\mathbb{R} \widetilde{a}( t-\tau,y,\xi)\phi^2(\tau)\exp\para{-\frac{1}{2}\int_0^{ t}\widetilde{a}(s-\tau,y,\xi)ds}
\Psi(\xi)  \, \mathrm{d} \tau \,
\mathrm{d}\omega_y(\xi)\cr
=2\int_\mathbb{R}\phi^2(\tau) \!\!\int_{S^+_{y}\mathrm{M}_1}\int_0^T \frac{d}{dt}\exp\para{-\frac{1}{2}\int_0^{ t}\widetilde{a}(s-\tau,y,\xi)ds}
\Psi(\xi)  \, \mathrm{d} \tau \,
\mathrm{d}\omega_y(\xi)\cr
=2\int_\mathbb{R}\phi^2(\tau) \!\!\int_{S^+_{y}\mathrm{M}_1}\cro{\exp\para{-\frac{1}{2}\int_0^{ T}\widetilde{a}(s-\tau,y,\xi)ds}-1}
\Psi(\xi)  \, \mathrm{d} \tau \,
\mathrm{d}\omega_y(\xi).
\end{multline}
By the support properties of the function $\phi$, we get that the left-hand side term in (\ref{4.14}) reads
\begin{multline*}
  \int_\mathbb{R}\phi^2(\tau) \!\!\int_{S^+_{y}\mathrm{M}_1}\cro{\exp\para{-\frac{1}{2}\int_0^{T}\widetilde{a}(s-\tau,y,\xi)ds}-1}
\Psi(\xi)  \, \mathrm{d} \tau \,
\mathrm{d}\omega_y(\xi)=\cr
\int_{S^+_{y}\mathrm{M}_1}\cro{\exp\para{-\frac{1}{2}\int_0^{\ell_+(y,\xi)}\widetilde{a}(s,y,\xi)ds}-1}
\Psi(\xi) \mu(y,\xi) \, 
\mathrm{d}\omega_y(\xi).
\end{multline*}
Then, by (\ref{4.14}) and (\ref{4.2}) we get
\begin{multline}\label{4.15}
\abs{\int_{S^+_{y}\mathrm{M}_1}\para{\exp\para{-\frac{1}{2}\mathcal{I}(a)(y,\xi)}-1}
\Psi(\xi)  \,  
\mathrm{d}\omega_y(\xi)}\cr
 \leq C\para{h+h^{-2}\norm{\Lambda_{a_1,q_1}-\Lambda_{a_2,q_2}}} \norm{\Psi}_{H^2(S_y\mathrm{M}_{1})}.
\end{multline}
This completes the proof of the Lemma.

As in Lemma \ref{L.4.2}, we take two solutions to (\ref{3.11}) of the form
\begin{align*}
\widetilde{\theta}_1(t,r,\xi)&=\alpha^{-1/4}\phi(t-r)\Psi(\xi), \\
\widetilde{\theta}_2(t,r,\xi)&=\alpha^{-1/4}\phi(t-r).
\end{align*}
We change variable in the left term of (\ref{5.2}), $x=\exp_{y}(r\xi)$, $r>0$ and $\xi\in S_{y}\mathrm{M}_1$. We have
\begin{multline}\label{5.8}
\int_0^T\!\!\int_\mathrm{M} q(x) (\overline{\theta}_1\theta_2)(x,t) \,\mathrm{dv}^{n} \, \mathrm{d} t \cr
=\int_0^T\!\!\int_{S_{y}\mathrm{M}_1}\!\int_0^{\ell_+(y,\xi)}\widetilde{q}(r,y,\xi)(\overline{\widetilde{\theta}}_1\widetilde{\theta}_2)( t,r,\xi)
\alpha^{1/2} \, \mathrm{d} r \, \mathrm{d}\omega_y(\xi) \, \mathrm{d} t\cr
=\int_0^T\!\!\int_{S_{y}\mathrm{M}_1}\!\int_0^{\ell_+(y,\xi)}\widetilde{q}(r,y,\xi)\phi^2( t-r)\Psi(\xi)  \, \mathrm{d} r \,
\mathrm{d}\omega_y(\xi)
\, \mathrm{d} t.
\end{multline}
By support properties of the function $\phi$, we get
$$\int_0^T\!\!\int_\mathrm{M} q(x) (\overline{\theta}_1\theta_2)(x,t) \,\mathrm{dv}^{n} \, \mathrm{d} t=\bigg(\int_\mathbb{R}\phi^2(t)\,dt \bigg) \!\!\int_{S_{y}\mathrm{M}_1}\mathcal{I} q(y,\xi)
\Psi(\xi)  \,  \,
\mathrm{d}\omega_y(\xi).
$$
Then, by (\ref{5.2}), we get
\begin{equation}\label{5.9}
\bigg|\int_{S_{y}\mathrm{M}_1}\mathcal{I} q(y,\xi)
\Psi(\xi)  \,  \,
\mathrm{d}\omega_y(\xi)\bigg|
\leq C\para{h+h^{-1} \|a\|_{\mathcal{C}^0(\mathrm{M})}+h^{-3}\norm{\Lambda_{a_1,q_1}
-\Lambda_{a_2,q_2}}
} \norm{\Psi}_{H^2(S^+_y\mathrm{M}_{1})}.
\end{equation}
This compete the proof.

