we deduce that 
 $$
 \bigg|\int_0^T\!\!\!\int_\mathrm{M} q(x)(\theta_2\overline{\theta}_1)(x,t)(1-\psi_{a}(x,t))\,\,\mathrm{dv}^{n} dt\bigg| \leq C\norm{a}_{\mathcal{C}^0(\mathrm{M})} \norm{\theta_1}_{\mathcal{V}(Q)}\norm{\theta_2}_{\mathcal{V}(Q)}.$$ Combining with (\ref{5.4}), (\ref{5.5}) and (\ref{5.6}), the estimate (\ref{5.2}) follows.\\
  This completes the proof of the Lemma.

By density arguments, it suffices to prove the theorem for $f \in \mathcal{C}^{\infty}(\mathrm{M})$. Indeed, if $f\in H^1(M)$, then we can find  a sequence $(f_k)_k$ in $\mathcal{C}^{\infty}(\mathrm{M})$ converging towards $f$ in $H^1(\mathrm{M}).$

 The ray transform $\mathcal{I}$ is a bounded operator from $H^1(\mathrm{M})$ into $H^1(\partial_+S\mathrm{M})$, so the sequence $(\mathcal{I} f_k)_k$ converges towards $\mathcal{I} f$ in $H^1(\partial_+S\mathrm{M}).$ Applying the theorem for $f_k$ and passing to the limit as $k \rightarrow +\infty,$ we deduce that $ \Vert f \Vert _{L^2(\mathrm{M})}\leq C \Vert \mathcal{I} f \Vert_{H^1(\partial_+S\mathrm{M})}$.
  \smallskip

   Before starting the proof of the theorem, we need to introduce some notions and notations. We will use the Einstein summation convention to abbreviate the notations. When an index variable appears twice in a simple term and is not otherwise defined, it implies summation of that term over all the values of the index. For example, for $i\in{1,2,3}$, $c_ix^i$ means $c_1x^1+c_2x^2+c_3x^3$.
\smallskip

Let $\tau_s^r\mathrm{M}$ be the bundle of tensors of degree $(r,s)$ on $\mathrm{M}$. Its sections denoted by $T_s^r$ are called \textit{tensor fields of degree $(r,s)$.} Let $U$ be a domain of $\mathrm{M}
$.
 We denote by $\mathcal{C}^{\infty}(\tau_s^r\mathrm{M},U)$ the $\mathcal{C}^{\infty}(U)$-module of smooth sections of the bundle $\tau_s^r \mathrm{M}$ over $U$. The notation $\mathcal{C}^{\infty}(\tau_s^r\mathrm{M},\mathrm{M})$ will usually be abbreviated to $\mathcal{C}^{\infty}(\tau_s^r\mathrm{M}).$
  If $(x^1,\dots,x^n)$ is a local coordinate system defined in a domain $U$, then any tensor field $u\in \mathcal{C}^{\infty}(\tau_s^r \mathrm{M},U)$ can be uniquely represented as
\begin{equation}\label{2.11}
u=u_{j_1,\dots,j_s}^{i_1,\dots,i_r} \frac{\partial}{\partial x^{i_1}}\otimes\dots\otimes\frac{\partial}{\partial x^{i_r}}\otimes dx^{j_1} \otimes \dots \otimes dx^{j_s},
\end{equation}
where $u_{j_1,\cdots,j_s}^{i_1,\cdots,i_r} \in \mathcal{C}^{\infty}(U)$ are called the coordinates of the field $u$ in the given coordinate system. We will usually abbreviate (\ref{2.11}) as follows
\begin{equation}\label{2.12}
 u=(u_{j_1,\cdots,j_s}^{i_1,\cdots,i_r}).
\end{equation}
The bundles $\tau_s^r \mathrm{M}$ and $\tau_r^s \mathrm{M}$ are dual to each other and, consequently, $\mathcal{C}^{\infty}(\tau_s^r \mathrm{M})$ and $\mathcal{C}^{\infty}(\tau_r^s \mathrm{M})$ are mutually dual $\mathcal{C}^{\infty}(\mathrm{M})$-modules. This implies in particular that a field $u\in \mathcal{C}^{\infty}(\tau_s^1 \mathrm{M})$ can be considered as a $\mathcal{C}^{\infty}(\mathrm{M})$-multilinear mapping $u:\mathcal{C}^{\infty}(\tau_0^1 \mathrm{M})\times\dots\times\mathcal{C}^{\infty}(\tau_0^1 \mathrm{M})\longrightarrow \mathcal{C}^{\infty}(\tau_0^1 \mathrm{M}).$ Consequently, a given connection $\nabla$ on $\mathrm{M}$ defines the $\mathbb{C}$-linear mapping (denoted by the same letter)
\begin{equation}\label{2.13}
\nabla:\mathcal{C}^{\infty}(\tau_0^1 \mathrm{M})\longrightarrow \mathcal{C}^{\infty}(\tau_1^1 \mathrm{M})
\end{equation}  by the formula $(\nabla v)(u)=\nabla_uv,$ 
The tensor field $\nabla v$ is called the \textit{covariant derivative} of the vector field $v$ (with respect to the given connection). The covariant differenciation defined on vector fields can be transferred to tensor fields ( see \cite{[Sh]} Theorem 3.2.1 pp. 85)
\begin{equation}\label{2.14}
\nabla:\mathcal{C}^{\infty}(\tau_s^r \mathrm{M})\longrightarrow \mathcal{C}^{\infty}(\tau_{s+1}^r \mathrm{M})
\end{equation}
such that (\ref{2.14}) coincides with the mapping (\ref{2.13}), for $r=1$ and $s=0$ and that for a field $$u=u_{j_1,\dots,j_s}^{i_1,\dots,i_r} \frac{\partial}{\partial x^{i_1}}\otimes\dots\otimes\frac{\partial}{\partial x^{i_r}}\otimes dx^{j_1} \otimes \dots \otimes dx^{j_s},$$ the field $\nabla u$ is defined by $$\nabla u=\nabla_ku_{j_1,\dots,j_s}^{i_1,\dots,i_r}  \frac{\partial}{\partial x^{i_1}}\otimes\dots\otimes\frac{\partial}{\partial x^{i_r}}\otimes dx^{j_1} \otimes \dots \otimes dx^{j_s}\otimes dx^k,$$ where 
\begin{equation}\label{2.15}
\nabla_ku_{j_1\dots j_s}^{i_1\dots i_r} =\frac{\partial}{\partial x^k}u_{j_1\dots j_s}^{i_1 \dots i_r}+\sum_{m=1}^r\Gamma^{i_m}_{kp}u_{j_1 \dots j_s}^{i_1 \dots i_{m-1} p i_{m+1} \dots i_r}-\sum_{m=1}^s\Gamma^{p}_{kj_m}u_{j_1 \dots j_{m-1} p j_{m+1} \dots j_s}^{i_1 \dots  i_r},
\end{equation}
where $\Gamma_{kq}^p$ is the Christoffel symbol.

Now, we will extend this covariant differenciation for tensors on $T\mathrm{M}$. If $(x^1,\dots, x^n)$ is a local coordinate system  defined in a domain $U \subset \mathrm{M}$, then we denote by $\frac{\partial}{\partial x^i}$ the coordinate vector fields and by $dx^i$ the coordinate covector fields. We recall that the coordinates of a vector $\xi \in T_x\mathrm{M}$ are the coefficients of the expansion $\xi=\xi^i \frac{\partial}{\partial x^i}$. Let $p$ be the projection on $\mathrm{M}$. On the domain $p^{-1}(U)\subset T\mathrm{M}$, the family of the functions $(x^1, \dots,x^n,\xi^1,\dots,\xi^n)$ is a local coordinate system which is called \textit{associated} with the system $(x^1,\dots,x^n).$ A local coordinate system  on $T\mathrm{M}$ will be called a \textit{natural coordinate system} if it is associated with some local coordinate system on $\mathrm{M}$. In the sequel, we will use only such coordinate systems on $T\mathrm{M}$. The algebra of tensor fields of the manifold $T\mathrm{M}$ is generated locally by the coordinate fields $\frac{\partial}{\partial x^i},\frac{\partial}{\partial \xi^i}, dx^i, d\xi^i.$ A tensor $u \in T^r_{s,(x,\xi)}(T\mathrm{M})$ of degree $(r,s)$ at a point $(x,\xi)\in T\mathrm{M}$ is called \textit{semibasic} if in some (and so, in any) natural coordinate system, it can be represented as:
\begin{equation}\label{2.16}
u=u_{j_1 \dots j_s}^{i_1 \dots i_r} \frac{\partial}{\partial \xi^{i_1}}\otimes\dots\otimes\frac{\partial}{\partial \xi^{i_r}}\otimes dx^{j_1} \otimes \dots \otimes dx^{j_s}.
\end{equation}
We will abbreviate this equality to $$u=(u_{j_1 \dots j_s}^{i_1 \dots i_r} ).$$ We denote by $\beta_s^r\mathrm{M}$ the subbundle in $\tau_s^r(T\mathrm{M})$ made of all semibasic tensors of degree $(r,s).$ Note that $\mathcal{C}^{\infty}(\beta_0^0 \mathrm{M})=\mathcal{C}^{\infty}(T \mathrm{M})$. The elements of $\mathcal{C}^{\infty}(\beta_0^1 \mathrm{M})$ are called the \textit{semibasic vector fields}, and the elements of $\mathcal{C}^{\infty}(\beta_1^0 \mathrm{M})$ are called \textit{semibasic covector fields}.
Tensor fields on $M$ can be identified with the semibasic tensor fields on $T\mathrm{M}$ whose components are independent of the second argument $\xi$. Thus we obtain the canonical imbedding
\begin{equation}\label{2.17}
\iota:\mathcal{C}^{\infty}(\tau_s^r \mathrm{M}) \subset \mathcal{C}^{\infty}(\beta_s^r \mathrm{M}).
\end{equation}
Note that $\iota( \frac{\partial}{\partial x^{i}})= \frac{\partial}{\partial \xi^{i}}$ and $\iota(dx^i)=dx^i.$
\smallskip

For $u\in \mathcal{C}^{\infty}(\beta_s^r \mathrm{M})$, we define two semibasic tensor fields $\overset{\mathrm{v}}{\nabla}u$ and $\overset{\mathrm{h}}{\nabla}u$ by the formulas 
\begin{equation}\label{2.18}
\overset{\mathrm{v}}{\nabla}u =\overset{\mathrm{v}}{\nabla}_k u_{j_1 \dots j_s}^{i_1 \dots i_r} \frac{\partial}{\partial \xi^{i_1}}\otimes\dots\otimes\frac{\partial}{\partial \xi^{i_r}}\otimes dx^{j_1} \otimes \dots \otimes dx^{j_s}\otimes dx^k,
\end{equation}
where
\begin{equation}\label{2.19}
\overset{\mathrm{v}}{\nabla}_k u_{j_1 \dots j_s}^{i_1 \dots i_r}=\frac{\partial }{\partial \xi^k} u_{j_1 \dots j_s}^{i_1 \dots i_r},
\end{equation}
and 
\begin{equation}\label{2.20}
\overset{\mathrm{h}}{\nabla}u =\overset{\mathrm{h}}{\nabla}_k u_{j_1 \dots j_s}^{i_1 \dots i_r} \frac{\partial}{\partial \xi^{i_1}}\otimes\dots\otimes\frac{\partial}{\partial \xi^{i_r}}\otimes dx^{j_1} \otimes \dots \otimes dx^{j_s}\otimes dx^k,
\end{equation}
where
\begin{multline}\label{2.21}
\overset{\mathrm{h}}{\nabla}_ku_{j_1\dots j_s}^{i_1\dots i_r} =\frac{\partial}{\partial x^k}u_{j_1\dots j_s}^{i_1 \dots i_r}-\Gamma^{p}_{kq}\xi^q \frac{\partial}{\partial \xi^{p}}u_{j_1\dots j_s}^{i_1\dots i_r}\cr
+\sum_{m=1}^r\Gamma^{i_m}_{kp}u_{j_1 \dots j_s}^{i_1 \dots i_{m-1} p i_{m+1} \dots i_r}-\sum_{m=1}^s\Gamma^{p}_{kj_m}u_{j_1 \dots j_{m-1} p j_{m+1} \dots j_s}^{i_1 \dots  i_r}.
\end{multline}
\smallskip

We thus obtain two well-defined differential operators $\overset{\mathrm{v}}{\nabla}, \overset{\mathrm{h}}{\nabla}:\mathcal{C}^{\infty}(\beta_s^r \mathrm{M})\longrightarrow \mathcal{C}^{\infty}(\beta_{s+1}^r \mathrm{M})$ that are respectively called the \textit{vertical} and \textit{horizontal} covariant derivatives.\\
For $u\in\mathcal{C}^\infty(T\mathrm{M})$ the covariant field $\overset{\mathrm{h}}{\nabla} u\in\mathcal{C}^\infty(T^*\mathrm{M})$ given in a coordinates system by
\begin{equation}\label{2.22}
\overset{\mathrm{h}}{\nabla} u=(\overset{\mathrm{h}}{\nabla}_k u)dx^k,\quad \overset{\mathrm{h}}{\nabla}_k u=\frac{\partial u}{\partial x^k}-\Gamma_{kq}^p\xi^q\frac{\partial u}{\partial\xi^p}.
\end{equation}
The vertical covariant derivative of $u$ is given by
\begin{equation}\label{2.23}
\overset{\mathrm{v}}{\nabla}u=(\overset{\mathrm{v}}{\nabla}_ku)dx^k,\quad \overset{\mathrm{v}}{\nabla}_ku=\frac{\partial u}{\partial\xi^k}.
\end{equation}
We can show that these derivatives satisfy the following commutation formulas (for more details, see \cite{[Sh]}, pp. 95).
\begin{equation}\label{2.24}
\overset{\mathrm{v}}{\nabla}_k \overset{\mathrm{h}}{\nabla}_l=\overset{\mathrm{h}}{\nabla}_l\overset{\mathrm{v}}{\nabla}_k.
\end{equation} 
We can also prove the following relations
\begin{equation}\label{2.25}
\overset{\mathrm{h}}{\nabla}_k\xi^i=0,\quad \overset{\mathrm{v}}{\nabla}_k\xi^i=\delta_k^i.
\end{equation}
As can be easily shown, $\overset{\mathrm{v}}{\nabla}$ and $\overset{\mathrm{h}}{\nabla}$ are well-defined first-order differential operators. In particular, they extend naturally to the Sobolev space $H^1(\beta^r_s\mathrm{M})$.

The vertical divergence, $\overset{\mathrm{v}}{\textrm{div}}$, and the horizontal divergence, $\overset{\mathrm{h}}{\textrm{div}}$, of a semibasic vector field $V$ are defined by
\begin{equation}\label{2.26}
 \overset{\mathrm{v}}{\textrm{div}}(V)= \overset{\mathrm{v}}{\nabla}_k v^k,\quad  \overset{\mathrm{h}}{\textrm{div}}(V)= \overset{\mathrm{h}}{\nabla}_k v^k.
\end{equation}
\smallskip

To prove Theorem \ref{theorem}, we also need the two following divergence formulas   (see \cite{[Sh]}, p 101).\\
\textit{Gauss-Ostrogradskii formula} of the vertical divergence
\begin{equation}\label{2.27}
\int_{S\mathrm{M}} \overset{\mathrm{v}}{\textrm{div}}(W)\, \,\mathrm{dv}^{2n-1}=(n-2) \int_{S\mathrm{M}} \langle W,\xi\rangle \, \,\mathrm{dv}^{2n-1},\quad W\in \mathcal{C}^\infty(T\mathrm{M}),
\end{equation}
\textit{Gauss-Ostrogradskii formula} of the horizontal divergence
\begin{equation}\label{2.28}
\int_{S\mathrm{M}} \overset{\mathrm{h}}{\textrm{div}}(V)\, \,\mathrm{dv}^{2n-1}= \int_{\partial S\mathrm{M}} \langle V,\nu\rangle \, \,\mathrm{d\sigma}^{2n-2}, \quad V\in \mathcal{C}^\infty(T\mathrm{M}),
\end{equation}
Let $H$ denote the vector field associated with the geodesic flow $\phi_t$. For $u\in \mathcal{C}^\infty(S\mathrm{M})$ and $(x,\xi)\in S\mathrm{M}$, we have
\begin{equation}\label{2.29}
Hu(x,\xi)=\frac{d}{dt}u(\phi_t(x,\xi))_{|t=0}.
\end{equation}    
and we call it the differentiation along the geodesics. In coordinate form, we have 
\begin{equation}\label{2.30}
H=\xi^i\frac{\partial}{\partial x^i}-\Gamma^i_{jk}\xi^j\xi^k\frac{\partial}{\partial \xi^i}=\xi^i (\frac{\partial}{\partial x^i}-\Gamma^p_{iq}\xi^q \frac{\partial}{\partial \xi^p})=\xi^i\overset{\mathrm{h}}{\nabla}_i.
\end{equation}
Now we consider the \textit{Pestov identity}, which is the basic energy identity that has been used since the work of Mukhometov \cite{[Mukh]} in most injectivity proofs of ray transforms in absence of real-analyticity or special symmetries. For a function $u \in \mathcal{C}^{\infty}(T \mathrm{M})$, we have
\begin{equation}\label{2.31}
2\langle  \overset{\mathrm{h}}{\nabla} u,  \overset{\mathrm{v}}{\nabla}Hu \rangle=\vert  \overset{\mathrm{h}}{\nabla} u \vert^2+  \overset{\mathrm{h}}{\textrm{div}}(V) + \overset{\mathrm{v}}{\textrm{div}}(W)- \langle R(\xi,\overset{\mathrm{v}}{\nabla} u)\xi,  \overset{\mathrm{v}}{\nabla} u\rangle.
\end{equation}
Here $H$ is the geodesic vector field associated with the geodesic flow given by (\ref{2.29}), $R$ is the curvature tensor, and the semibasic vector $V$ and $W$ are given by
 \begin{equation}\label{2.32}
  V = \langle \overset{\mathrm{h}}{\nabla} u, \overset{\mathrm{v}}{\nabla} u\rangle\xi-\langle\xi, \overset{\mathrm{h}}{\nabla} u\rangle  \overset{\mathrm{v}}{\nabla} u,
\end{equation}   
 \begin{equation}\label{2.33}
 W=\langle\xi,\overset{\mathrm{h}}{\nabla} u\rangle  \overset{\mathrm{h}}{\nabla} u.
 \end{equation}
 We introduce the function $u:S\mathrm{M}\to\mathbb{R}$ defined by 
   \begin{equation}\label{2.34}
    u(x,\xi)=\int_0^{\ell_+(x,\xi)}f(\gamma_{x,\xi}(t)) dt.
   \end{equation}
  It satisfies the boundary conditions 
  \begin{equation}\label{2.35}
  u=\mathcal{I} f,\quad\mbox{on }\partial_+ S\mathrm{M},
  \end{equation}
    and, since $\ell_+(x,\xi)=0$ for $(x,\xi)\in \partial_- S\mathrm{M}$, we have
    \begin{equation}\label{2.36}
     u=0,\quad\mbox{on }\partial_- S\mathrm{M}.
\end{equation}

\begin{proof}
By the simplicity assumption, since $y\notin\overline{\mathrm{M}}$, we have $\varrho\in\mathcal{C}^\infty(\mathrm{M})$, and in polar normal coordinates, we get
\begin{equation}\label{3.8}
\widetilde{\varrho}(r,\xi)=r=d_\mathrm{g}(y,x).
\end{equation}
The proof is complete.
\end{proof}

Let us introduce the following spaces:
\begin{equation}\label{3.9}
\mathcal{V}(Q)=\set{\theta\in H^3(0,T;L^2(\mathrm{M}))\cap H^1(0,T;H^2(\mathrm{M})),\,\,\partial_t^j\theta(\cdot,0)=\partial_t^j\theta(\cdot,T)=0,\,j=0,1,2.},
\end{equation}
and
\begin{equation}\label{3.10}
\mathcal{W}(Q)=\set{\psi\in W^{2,\infty}(Q),\,\, \partial_t\psi\in W^{2,\infty}(Q)},
\end{equation}
equipped with the norms:
\begin{eqnarray*}
\norm{\theta}_{\mathcal{V}(Q)}&:=&\norm{\theta}_{H^1(0,T;H^2(\mathrm{M}))}+\norm{\theta}_{H^3(0,T;L^2(\mathrm{M}))}, \quad \theta\in\mathcal{V}(Q),\cr
\\
\norm{\psi}_{\mathcal{W}(Q)}&:=&\norm{\psi}_{W^{2,\infty}(Q)}+\norm{\partial_t\psi}_{W^{2,\infty}(Q)},\quad \psi\in\mathcal{W}(Q).
\end{eqnarray*}
We want to find a function $\theta\in \mathcal{V}(Q)$ which solves the first transport equation
\begin{equation}\label{3.11}
\partial_t \theta+\seq{d\varrho,d\theta}+\frac{1}{2} (\Delta \varrho)\theta=0,\qquad \forall t\in\mathbb{R},\, x\in\mathrm{M},
\end{equation}
where $\varrho$ is given by Lemma \ref{L.3.1}.\\
Moreover for $a\in W^{2,\infty}(\mathrm{M}) $, we need to find a function  
$\psi_a\in\mathcal{W}(Q) $ which solves the second transport equation
\begin{equation}\label{3.12}
\partial_t \psi_a+\seq{d\varrho,d\psi_a}+\frac{a}{2}\psi_a=0,\qquad \forall t\in\mathbb{R},\, x\in\mathrm{M}.
\end{equation}


The first step is to solve the transport equation (\ref{3.11}). Recall that
if $f(r)$ is any function of the geodesic distance $r$, then
\begin{equation}\label{3.13}
\Delta_{\widetilde{\mathrm{g}}}f(r)=f''(r)+\frac{\alpha^{-1}}{2}\frac{\partial
\alpha}{\partial r}f'(r).
\end{equation}
Here $\alpha=\alpha(r,\xi)$ denotes the square of the volume element in geodesic polar coordinates.
The transport equation (\ref{3.11}) becomes
\begin{equation}\label{3.14}
\frac{\partial \widetilde{\theta}}{\partial t}+\frac{\partial \widetilde{\varrho}}{\partial
r}\frac{\partial \widetilde{\theta}}{\partial
r}+\frac{1}{4}\widetilde{\theta}\alpha^{-1}\frac{\partial \alpha}{\partial r}\frac{\partial
\widetilde{\varrho}}{\partial r}=0.
\end{equation}
Thus $\widetilde{\theta}$ satisfies
\begin{equation}\label{3.15}
\frac{\partial \widetilde{\theta}}{\partial t}+\frac{\partial \widetilde{\theta}}{\partial
r}+\frac{1}{4}\widetilde{\theta}\alpha^{-1}\frac{\partial \alpha}{\partial r}=0.
\end{equation}
Let $\phi\in\mathcal{C}_0^\infty(\mathbb{R})$ and $\Psi\in H^2(S^+_y\mathrm{M})$. Let us write $\widetilde{\theta}$ in the form
\begin{equation}\label{3.16}
\widetilde{\theta}(t,r,\xi)=\alpha^{-1/4}\phi(t-r)\Psi(\xi).
\end{equation}
Direct computations yield
\begin{equation}\label{3.17}
\frac{\partial \widetilde{\theta}}{\partial
t}(t,r,\xi)=\alpha^{-1/4}\phi'(t-r)\Psi(\xi),
\end{equation}
and, we find
\begin{equation}\label{3.18}
\frac{\partial \widetilde{\theta}}{\partial
r}(t,r,\xi)=-\frac{1}{4}\alpha^{-5/4}\frac{\partial\alpha}{\partial
r}\phi(t-r)\Psi(\xi)-\alpha^{-1/4}\phi'(t-r)\Psi(\xi).
\end{equation}
Finally, (\ref{3.18}) and (\ref{3.17}) yield
\begin{equation}\label{3.19}
\frac{\partial \widetilde{\theta}}{\partial t}(t,r,\xi)+\frac{\partial \widetilde{\theta}}{\partial
r}(t,r,\xi)=-\frac{1}{4}\alpha^{-1}\widetilde{\theta}(t,r,\xi)\frac{\partial\alpha}{\partial
r}.
\end{equation}
Now if we assume that $\mathrm{supp}(\phi) \subset (0,\epsilon)$,  then for any $x=\exp_y(r\xi)\in \mathrm{M}$, it is easy to
see that 
$$
\partial_t^j\widetilde{\theta}(0,r,\xi)=\partial_t^j\widetilde{\theta}(T,r,\xi)=0,\quad j=0,1,2,\,\, T-r>\varepsilon.
$$
For the second transport equation (\ref{3.12}), in polar coordinates, takes the form
\begin{equation}\label{3.20}
\frac{\partial \widetilde{\psi}_a}{\partial t}+\frac{\partial \widetilde{\varrho}}{\partial
r}\frac{\partial \widetilde{\psi}_a}{\partial
r} +\frac{1}{2}\widetilde{a}(r,y,\xi)\widetilde{\psi}_a=0,
\end{equation}
where $\widetilde{a}(r,y,\xi):=a(\theta_r(y,\xi))$. Thus $\widetilde{\psi}_a$ satisfies
\begin{equation}\label{3.21}
\frac{\partial \widetilde{\psi}_a}{\partial t}+\frac{\partial \widetilde{\psi}_a}{\partial
r}+\frac{1}{2}\widetilde{a}(r,y,\xi)\widetilde{\psi}_a=0.
\end{equation}
Thus, we can choose $\widetilde{\psi}_a$ as following
\begin{equation}\label{3.22}
\widetilde{\psi}_a(t,y,r,\xi)=\exp\para{-\frac{1}{2}\int_0^t\widetilde{a}(r-s,y,\xi)ds}.
\end{equation}
Since $a\in W^{2,\infty}(\mathrm{M})$, we get $\psi_a\in \mathcal{W}(Q)$. Hence (\ref{3.12}) is solved.

\begin{proof}
Let $r(x,t;h)$ solves the following 
homogenous boundary value problem
\begin{equation}\label{3.26}
\left\{
\begin{array}{llll}
\para{\partial^2_t-\Delta+a(x)\partial_t+q(x)}r(x,t)=V_h (x,t)
& \textrm{in }\,\, Q,\cr
r(x,0)=\partial_tr(x,0)=0,& \textrm{in
}\,\,\mathrm{M},\cr
r(x,t)=0 & \textrm{on} \,\, \Sigma.
\end{array}
\right.
\end{equation}
where the source term $V_h$ is given by 
\begin{equation}\label{3.27}
V_h(x,t)=-\para{\partial_t^2-\Delta+a(x)\partial_t+q(x)}\para{(\theta\psi_a)(x,t)e^{i\varphi/h}}.
\end{equation}
To prove our Lemma it would be enough to show that $r$ satisfies the estimates (\ref{3.25}).\\
By a simple computation, we have
\begin{align}\label{3.28}
-V_h (x,t)&=e^{i\varphi(x,t)/h}\para{\partial_t^2-\Delta+a(x)\partial_t+q(x)}\para{(\theta\psi_a)( x,t)}\cr
&\quad -\frac{2i}{h} e^{i\varphi(x,t)/h}\psi_a(x,t)\para{\partial_t\theta+\seq{d\varrho,d\theta}+\frac{\theta}{2}\Delta\varrho}( x,t)\cr
&\quad -\frac{2i}{h} e^{i\varphi(x,t)/h}\theta(x,t)\para{\partial_t\psi_a+\seq{d\varrho,d\psi_a}+\frac{a}{2} \psi_a}(x,t)\cr
&\quad-\frac{1}{h^2} \theta\psi_a(x,t) e^{i\varphi(x,t)/h}\para{1-\abs{d\varrho}^2}.
\end{align}
Taking into account  (\ref{3.7})-(\ref{3.11}) and (\ref{3.12}), the right-hand side of (\ref{3.28}) becomes
\begin{align}\label{3.29}
V_h (x,t)&=-e^{i\varphi(x,t)/h}(\partial_t^2-\Delta+a(x)\partial_t+q(x))\para{(\theta\psi_a)(x,t)}
\cr &\equiv-e^{i\varphi(x,t)/h}V_0(x,t).
\end{align}
Since $\theta\in\mathcal{V}(Q)$ and $\psi_a\in\mathcal{W}(Q)$ we deduce that $V_0\in H^1_0(0,T;L^2(\mathrm{M}))$. 
Furthermore, there is a constant $C>0$, such that
\begin{equation}\label{3.30}
\norm{V_0}_{L^2(Q)}+\norm{\partial_tV_0}_{L^2(Q)}\leq C\norm{\theta}_{\mathcal{V}(Q)}.
\end{equation}
By Lemma \ref{L.1.1}, we find
\begin{equation}\label{3.31}
r_h\in \mathcal{C}^2(0,T;L^2(\mathrm{M}))\cap\mathcal{C}^1(0,T;H^1_0(\mathrm{M}))\cap\mathcal{C}(0,T;H^2(\mathrm{M})).
\end{equation}
Since the coefficients $a$ and $q$ do not depend on $t$, the function
$$
r^*_h(x,t)=\int_0^tr_h(x,s)ds,
$$
solves the mixed hyperbolic problem (\ref{3.26}) with the right side
$$
V^*_h(x,t)=\int_0^tV_h (x,s)ds=-ih\int_0^tV_0(x,s)\partial_s\para{e^{i\varphi(x,s)/h}}ds.
$$
Integrating by part with respect to $s$, we conclude that
$$
\norm{V^*_h}_{L^2(Q)}\leq Ch\norm{\theta}_{\mathcal{V}(Q)}.
$$
and by (\ref{1.5}), we get
\begin{eqnarray}\label{3.32}
\norm{r_h(\cdot,t)}_{L^2(\mathrm{M})}=\norm{\partial_tr^*_h(\cdot,t)}_{L^2(\mathrm{M})}\leq
Ch\norm{\theta}_{\mathcal{V}(Q)}.
\end{eqnarray}
Since $\norm{V_h }_{L^2(Q)}+h\norm{\partial_tV_h }_{L^2(Q)}\leq C\norm{\theta}_{\mathcal{V}(Q)}$, by using again the energy estimates for the problem (\ref{3.26}), obtain
\begin{eqnarray}\label{3.33}
\norm{\partial_tr_h(\cdot,t)}_{L^2(\mathrm{M})}+\norm{\nabla r_h (\cdot,t)}_{L^2(\mathrm{M})}\leq C\norm{\theta}_{\mathcal{V}(Q)}.
\end{eqnarray}
and by (\ref{1.6}), we have
